domain.ensure_application_schema.6.sql:
DECLARE @erp_owns_transaction BIT=CASE WHEN @@TRANCOUNT=0 THEN 1 ELSE 0 END;
BEGIN TRY
    IF @erp_owns_transaction=1 BEGIN TRANSACTION;
    DECLARE @erp_id INT;
    SELECT @erp_id=ISNULL(MAX(Id),0)+1 FROM dbo.TrainingQuestions WITH (TABLOCKX,HOLDLOCK);
    DECLARE @erp_no NVARCHAR(50)=CONVERT(NVARCHAR(50),@erp_id);
    SET IDENTITY_INSERT dbo.TrainingQuestions ON;
    INSERT dbo.TrainingQuestions
                        (Id,QuestionNo,CategoryName,QuestionText,OptionsJson,CorrectIndex,Explanation,QuestionType,AnswerJson)
                        VALUES (@erp_id,@erp_no,?,?,?,?,?,N'single_choice',?);
    SET IDENTITY_INSERT dbo.TrainingQuestions OFF;
    IF @erp_owns_transaction=1 COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @erp_owns_transaction=1 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
    BEGIN TRY
        SET IDENTITY_INSERT dbo.TrainingQuestions OFF;
    END TRY
    BEGIN CATCH
        PRINT N'題庫編號設定未能還原';
    END CATCH;
    THROW;
END CATCH

domain.upsert_operations_manuals.4.sql:
DECLARE @erp_no NVARCHAR(50)=CONVERT(NVARCHAR(50),NEXT VALUE FOR dbo.TrainingDocumentsNumbers);
MERGE dbo.Company_TrainingDocument AS target
                    USING (SELECT ? AS file_name) AS source ON target.file_name=source.file_name
                    WHEN MATCHED THEN UPDATE SET title=?,role_category=?,source_size=?,source_modified=?,is_active=1,imported_at=SYSDATETIME()
                    WHEN NOT MATCHED THEN INSERT (source_kind,document_id,file_name,title,role_category,source_size,source_modified,is_active)
                    VALUES (N'manual',@erp_no,?,?,?,?,?,1);

